    }

    // buildContents lists the book's contents, or, if it has none, its
    // chapters, by number.
    function buildContents() {
        const entries = Array.isArray(book.toc) && book.toc.length ? book.toc
            : book.spine.map((s, i) => ({ label: `Part ${i + 1}`, item: s, frag: "", level: 1 }));
        const list = el("ol");
