            if (item) {
                page.postMessage({ type: "at", item, fraction: Math.round(scrolled() * 1e4) / 1e4, size }, "*");
            }
        };
        if (now === true) {
            tellNow();
        } else {
            telling = setTimeout(tellNow, 400);
