    tubes.frustumCulled = false;

    const moves = new THREE.BufferGeometry();
    moves.setAttribute("position", new THREE.BufferAttribute(g.travel.positions, 3));
    const travel = new THREE.LineSegments(moves, new THREE.LineBasicMaterial({ color: 0x8a8a8a, transparent: true, opacity: 0.4 }));
    travel.visible = false;
    const object = new THREE.Group();
    object.add(lines, tubes, travel);
    let asTubes = n <= MAX_TUBES;
    lines.visible = !asTubes;
    tubes.visible = asTubes;

    // Colouring: each segment's colour, linear (as three.js works: the
    // legend's sRGB colours made so), in both forms.
    const legend = el("div", { className: "model-legend", ariaLabel: "Colours" });
    const categories = g.types.map((t) => (t ? featureCategory(t) : "other"));
    const linear = (rgb) => {
        const c = new THREE.Color().setRGB(rgb[0], rgb[1], rgb[2], THREE.SRGBColorSpace);
        return [c.r, c.g, c.b].map((v) => Math.round(v * 255));
    };
    const hexLinear = (hex) => {
        const c = new THREE.Color(hex);
        return [c.r, c.g, c.b].map((v) => Math.round(v * 255));
    };
    const put = (s, [r, gr, b]) => {
        tubeColours[s * 3] = r; tubeColours[s * 3 + 1] = gr; tubeColours[s * 3 + 2] = b;
        lineColours[s * 6] = lineColours[s * 6 + 3] = r;
        lineColours[s * 6 + 1] = lineColours[s * 6 + 4] = gr;
        lineColours[s * 6 + 2] = lineColours[s * 6 + 5] = b;
    };
    const colour = (by) => {
        const how = COLOURINGS[by];
        if (by === "feature") {
            const each = categories.map((cat) => hexLinear(CATEGORIES[cat][1]));
            const used = new Set();
            for (let s = 0; s < n; s++) {
                used.add(categories[x.types[s]]);
                put(s, each[x.types[s]]);
            }
            legend.replaceChildren(el("ul", {}, ...Object.entries(CATEGORIES).filter(([k]) => used.has(k)).map(([, [name, c]]) =>
                el("li", {}, el("span", { className: "swatch", style: `background:#${c.toString(16).padStart(6, "0")}` }), name))));
        } else {
            const values = how.of(x), scale = how.scale ?? 1, span = valueRange(values, scale);
            // 64 steps of the ramp, made once.
            const steps = Array.from({ length: 64 }, (_, i) => linear(rampAt(i / 63))), none = hexLinear(NONE);
            let unknown = false;
            for (let s = 0; s < n; s++) {
                const v = values[s] * scale;
                if (!span || !Number.isFinite(v)) { put(s, none); unknown = true; continue; }
                put(s, steps[Math.round(Math.max(0, Math.min(1, (v - span[0]) / (span[1] - span[0]))) * 63)]);
            }
            const said = span ? [shown(span[0], span[1] - span[0]), shown(span[1], span[1] - span[0])] : ["", ""];
            const note = (by === "flow" || by === "width") && g.diameterGuessed ? `For ${g.filamentDiameter} mm filament (it doesn't say: guessed).` : "";
            legend.replaceChildren(el("p", { className: "model-ramp-name", textContent: `${how.name}${how.unit ? ` (${how.unit})` : ""}` }),
                el("div", { className: "model-ramp", style: `background:linear-gradient(to right,${RAMP.join(",")})` }),
                el("p", { className: "model-ramp-ends" }, el("span", { textContent: span ? said[0] : "not said" }), el("span", { textContent: said[1] })),
                ...(unknown && span ? [el("p", { className: "hint" }, el("span", { className: "swatch", style: "background:#8a8a8a" }), " not said")] : []),
                ...(note ? [el("p", { className: "hint", textContent: note })] : []));
        }
        printed.attributes.color.needsUpdate = true;
        tubesGeometry.attributes.iColor.needsUpdate = true;
    };
    colour("feature");

    let upTo = layers - 1, only = false;
    const label = el("span", { className: "hint model-layer-label", role: "status" });
    const show = () => {
        const from = only && upTo > 0 ? g.layers.extrudeEnd[upTo - 1] : 0, to = g.layers.extrudeEnd[upTo];
        printed.setDrawRange(from * 2, (to - from) * 2);
        tubesGeometry.instanceCount = to;
        uniforms.uFrom.value = from;
        const tFrom = only && upTo > 0 ? g.layers.travelEnd[upTo - 1] : 0;
        moves.setDrawRange(tFrom * 2, (g.layers.travelEnd[upTo] - tFrom) * 2);
        const z = g.layers.z[upTo];
        label.textContent = `Layer ${(upTo + 1).toLocaleString("en")} of ${layers.toLocaleString("en")}${Number.isFinite(z) ? ` · Z ${z.toFixed(2)} mm` : ""}`;
    };
    show();
    const tools = (redraw, { toggle }) => {
        const slider = el("input", { type: "range", className: "model-layer", min: "0", max: String(layers - 1), value: String(upTo), step: "1", ariaLabel: "Layers shown, up to" });
        slider.addEventListener("input", () => { upTo = Number(slider.value); show(); redraw(); });
        const colourIcons = { feature: "materials", speed: "speed", flow: "flow", width: "fit-width", height: "layer-only", temp: "temperature", fan: "fan" };
        const by = glyphChoice({ className: "model-colour", title: "Colour lines by", value: "feature",
            choices: Object.entries(COLOURINGS).map(([value, c]) => ({ value, label: c.name, icon: colourIcons[value] })),
            change(value) { colour(value); redraw(); },
        });
        const shape = toggle("", asTubes ? "Lines as laid: their width and height (click for thin lines)" : "Thin lines (click for lines as laid: their width and height)", asTubes, function (on) {
            asTubes = on;
            tubes.visible = on;
            lines.visible = !on;
            this.title = on ? "Lines as laid: their width and height (click for thin lines)" : "Thin lines (click for lines as laid: their width and height)";
            this.setAttribute("aria-label", this.title);
        }, "tubes");
        shape.classList.add("model-tubes");
        if (n > MAX_TUBES) shape.title += ` (slow: it has ${n.toLocaleString("en")} of them)`;
        return [by, shape, el("span", { className: "model-layers" }, slider, label),
            toggle("", "Show only the layer the slider is at", false, (on) => { only = on; show(); }, "layer-only"),
            toggle("", "Show the moves that don't extrude", false, (on) => { travel.visible = on; }, "travel")];
    };
    const notes = [g.truncated ? "only the first part is shown: it has too many moves" : "", g.skipped ? `${g.skipped.toLocaleString("en")} moves out of range left out` : ""].filter(Boolean);
    return {
        object, meshes: [], measure: lines, tools, legend,
        info: describeGCode(g) + (notes.length ? ` · ${notes.join("; ")}` : ""),
        stop: () => box.dispose(),
    };
}

files.tabtop/model-info.js:
// What the 3D preview (model-view.js) says of a model, worked out from its
// triangles and G-code's moves, not from what's drawn: its size, how many
// triangles, the volume it encloses; and whether a 3MF or AMF (a zip) is
// small enough, unpacked, to be read.

// The most a zipped model unpacks to (a 3MF, read in a worker: its XML
// must fit in a string), and the most files in it.
export const MAX_UNZIPPED = 400 << 20;
export const MAX_ZIP_ENTRIES = 20000;

// meshFacts is {triangles, min, max, volume} of the triangles positions
// (x, y, z of each corner) has, by index if given (three at a time): volume
// is what's enclosed, in cubic units, if the surface is closed and its
// triangles face out (otherwise less meaningful: it's the absolute sum).
export function meshFacts(positions, index = null) {
    const count = index ? index.length : positions.length / 3;
    const min = [Infinity, Infinity, Infinity], max = [-Infinity, -Infinity, -Infinity];
    for (let i = 0; i + 2 < positions.length; i += 3) {
        for (let c = 0; c < 3; c++) {
            const v = positions[i + c];
            if (v < min[c]) min[c] = v;
            if (v > max[c]) max[c] = v;
        }
    }
    let volume = 0;
    const at = (k) => (index ? index[k] : k) * 3;
    for (let k = 0; k + 2 < count; k += 3) {
        const a = at(k), b = at(k + 1), c = at(k + 2);
        const ax = positions[a], ay = positions[a + 1], az = positions[a + 2];
        const bx = positions[b], by = positions[b + 1], bz = positions[b + 2];
        const cx = positions[c], cy = positions[c + 1], cz = positions[c + 2];
        volume += (ax * (by * cz - bz * cy) - ay * (bx * cz - bz * cx) + az * (bx * cy - by * cx)) / 6;
    }
    return { triangles: Math.floor(count / 3), min, max, volume: Math.abs(volume) };
}

// combine is the facts of several meshes', together.
export function combine(facts) {
    const out = { triangles: 0, min: [Infinity, Infinity, Infinity], max: [-Infinity, -Infinity, -Infinity], volume: 0 };
    for (const f of facts) {
        out.triangles += f.triangles;
        out.volume += f.volume;
        for (let c = 0; c < 3; c++) {
            out.min[c] = Math.min(out.min[c], f.min[c]);
            out.max[c] = Math.max(out.max[c], f.max[c]);
        }
    }
    return out;
}

const number = (v, digits = 1) => v.toLocaleString("en", { maximumFractionDigits: digits, minimumFractionDigits: 0 });

// sizeText is "40 × 20 × 10 mm", of min and max, in unit ("" for none said).
export function sizeText(min, max, unit = "mm") {
    if (!min.every(Number.isFinite)) return "";
    return `${[0, 1, 2].map((c) => number(max[c] - min[c], 2)).join(" × ")}${unit ? ` ${unit}` : ""}`;
}

// durationText is "1 h 02 min", "3 min 05 s", of seconds.
export function durationText(s) {
    if (!Number.isFinite(s) || s < 0) return "";
    const h = Math.floor(s / 3600), m = Math.floor(s % 3600 / 60), sec = Math.round(s % 60);
    return h ? `${h} h ${String(m).padStart(2, "0")} min` : m ? `${m} min ${String(sec).padStart(2, "0")} s` : `${sec} s`;
}

const plural = (n, one) => `${n.toLocaleString("en")} ${one}${n === 1 ? "" : "s"}`;

// describeMesh is the info line of a model: "40 × 20 × 10 mm · 1,234
// triangles · 3.2 cm³" (cm³ from mm³: the units printing formats use).
// A scene's (glTF's, FBX's) is in its unit ("m"; "" for not said), without
// a volume (it's seldom a solid), with its textures: "… · 3 textures".
export function describeMesh(f, { unit = "mm", volume = true, textures = null } = {}) {
    const parts = [sizeText(f.min, f.max, unit), plural(f.triangles, "triangle")];
    if (volume && f.volume > 0) parts.push(`${number(f.volume / 1000, 2)} cm³`);
    if (textures) parts.push(plural(textures, "texture"));
    return parts.filter(Boolean).join(" · ");
}

// missingText is what's said of the files a model refers to that aren't
// there: "2 files it refers to aren't here: a.png, b.bin".
export function missingText(missing) {
    if (!missing.length) return "";
    const names = missing.map((m) => String(m).split(/[\\/]/).pop());
    const shown = names.slice(0, 3).join(", ") + (names.length > 3 ? ", …" : "");
    return `${missing.length === 1 ? "a file it refers to isn't" : `${missing.length} files it refers to aren't`} here: ${shown}`;
}

// describeGCode is the info line of a G-code file, parsed (see gcode.js).
export function describeGCode(g) {
    const layers = g.layers.z.length;
    const parts = [];
    if (g.bounds) parts.push(sizeText(g.bounds.min, g.bounds.max));
    parts.push(`${layers.toLocaleString("en")} layer${layers === 1 ? "" : "s"}`);
    if (g.filament > 0) parts.push(`${number(g.filament / 1000, 2)} m of filament`);
    if (g.time !== null) parts.push(`about ${durationText(g.time)}`);
    if (g.slicer) parts.push(g.slicer);
    return parts.join(" · ");
}

// zipTooBig is why a zip's files are too much to unpack, or "" if they
// aren't: more than MAX_ZIP_ENTRIES of them, or more than limit together.
// One that isn't a zip is "". It reads the zip's file list exactly as
// fflate's unzipSync does (which three.js's loaders and model-worker.js
// unzip with), so what's counted is what would be unpacked: the count of
// files "on this disk", and zip64's fields' low 32 bits, as it has them.
export function zipTooBig(bytes, limit = MAX_UNZIPPED) {
    const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
    const u16 = (at) => (at >= 0 && at + 2 <= bytes.length ? view.getUint16(at, true) : -1);
    const u32 = (at) => (at >= 0 && at + 4 <= bytes.length ? view.getUint32(at, true) : -1);
    let end = -1;
    for (let i = bytes.length - 22; i >= 0 && bytes.length - i <= 65558; i--) {
        if (u32(i) === 0x06054b50) { end = i; break; }
    }
    if (end < 0) return "";
    let count = u16(end + 8), at = u32(end + 16);
    let zip64 = u32(end - 20) === 0x07064b50;
    if (zip64) {
        const z = u32(end - 12);
        zip64 = u32(z) === 0x06064b50;
        if (zip64) {
            count = u32(z + 32);
            at = u32(z + 48);
        }
    }
    if (count < 0 || at < 0) return "its file list is damaged";
    if (count > MAX_ZIP_ENTRIES) return `it holds ${count.toLocaleString("en")} files`;
    let total = 0;
    for (let k = 0; k < count; k++) {
        if (u32(at) !== 0x02014b50) return "its file list is damaged";
        let size = u32(at + 24);
        const nameLen = u16(at + 28), extraLen = u16(at + 30), commentLen = u16(at + 32);
        if (size === 0xffffffff && zip64) {
            // Its real size, in zip64's extra field, first.
            for (let e = at + 46 + nameLen; e + 4 < at + 46 + nameLen + extraLen; e += 4 + u16(e + 2)) {
                if (u16(e) === 1) {
                    size = u32(e + 4) + u32(e + 8) * 4294967296;
                    break;
                }
            }
        }
        if (size < 0) return "its file list is damaged";
        total += size;
        if (total > limit) return `it unpacks to more than ${Math.round(limit / (1 << 20))} MB`;
        at += 46 + nameLen + extraLen + commentLen;
    }
    return "";
}

// The most triangles meshCheck looks at (and corners: three times as
// many), as its tables are some 150 bytes a triangle at most, and a million
// take a second or so: a model with more isn't checked.
export const MAX_CHECKED = 2e6;

// mix spreads a number's bits over all of them (murmur3's last step): a
// float's bits (whose low ones are mostly 0) hash well after it.
function mix(h) {
    h ^= h >>> 16;
    h = Math.imul(h, 0x85ebca6b);
    h ^= h >>> 13;
    h = Math.imul(h, 0xc2b2ae35);
    return (h ^ (h >>> 16)) >>> 0;
}

// meshCheck is how a mesh's surface holds together, for printing: its
// edges used by one face only (open: holes), by more than two (not
// manifold), and by two facing opposite ways (one of them inside out: its
// edge run the same way by both); and how many pieces it's in. Corners at
// the same place are the same corner (an STL's, or a 3MF's, triangles each
// have their own). positions as meshFacts has them, index if given. It's
// null for more than MAX_CHECKED triangles, or 3 * MAX_CHECKED corners.
export function meshCheck(positions, index = null) {
    const corners = index ? index.length : positions.length / 3;
    const triangles = Math.floor(corners / 3);
    // (Corners count too: an index can use few of many.)
    if (triangles > MAX_CHECKED || positions.length / 3 > 3 * MAX_CHECKED) return null;
    // Each corner's place, as one id: an open-addressed table of its
    // coordinates' bits (exactly the same place, the same id).
    const floats = positions instanceof Float32Array ? positions : Float32Array.from(positions);
    const raw = new Uint32Array(floats.buffer, floats.byteOffset, floats.length);
    // A coordinate's bits, -0's as 0's (the same place).
    const bit = (i) => (raw[i] === 0x80000000 ? 0 : raw[i]);
    // Its hashes seeded afresh each time (a mesh made to put its corners in
    // one slot, for a hash known in advance, can't be), and its probing
    // budgeted: past it, it's not checked (null), rather than slow.
    const seed = (Math.random() * 0x100000000) >>> 0;
    let budget = 64 * (positions.length / 3 + corners) + 1e6;
    const vertexCount = positions.length / 3;
    let size = 1;
    while (size < vertexCount * 2) size <<= 1;
    const table = new Int32Array(size).fill(-1), weld = new Int32Array(vertexCount);
    let ids = 0;
    const firstOf = new Int32Array(vertexCount);
    for (let v = 0; v < vertexCount; v++) {
        const a = bit(v * 3), b = bit(v * 3 + 1), c = bit(v * 3 + 2);
        // (The seed mixed in first: with it outermost, places made to share
        // a hash would share it whatever the seed.)
        let h = mix(a ^ mix(b ^ mix(c ^ seed))) & (size - 1);
        for (;;) {
            if (--budget < 0) return null;
            const at = table[h];
            if (at < 0) {
                table[h] = v;
                firstOf[v] = ids;
                weld[v] = ids++;
                break;
            }
            if (bit(at * 3) === a && bit(at * 3 + 1) === b && bit(at * 3 + 2) === c) {
                weld[v] = firstOf[at];
                break;
            }
            h = (h + 1) & (size - 1);
        }
    }
    // Each edge: how many faces use it, and which ways (+1 run low to
    // high, -1 high to low); a table keyed by its two corners' ids.
    // (Bigger than there may be edges: at most 3 a triangle, all apart; a
    // closed surface's are half that. Never more than three-quarters full.)
    let edgeSize = 1;
    while (edgeSize < triangles * 4) edgeSize <<= 1;
    const keys = new Float64Array(edgeSize).fill(-1), uses = new Int32Array(edgeSize), ways = new Int32Array(edgeSize);
    // Pieces: corners joined by a face are one.
    const parent = new Int32Array(ids);
    for (let i = 0; i < ids; i++) parent[i] = i;
    const root = (i) => {
        while (parent[i] !== i) { parent[i] = parent[parent[i]]; i = parent[i]; }
        return i;
    };
    // A corner's id; -1 for an index that isn't one of its corners.
    const corner = (k) => {
        const i = index ? index[k] : k;
        return Number.isInteger(i) && i >= 0 && i < vertexCount ? weld[i] : -1;
    };
    for (let t = 0; t < triangles; t++) {
        const v = [corner(t * 3), corner(t * 3 + 1), corner(t * 3 + 2)];
        if (v[0] < 0 || v[1] < 0 || v[2] < 0) continue; // not its corners
        if (v[0] === v[1] || v[1] === v[2] || v[0] === v[2]) continue; // no area: no edges
        for (let e = 0; e < 3; e++) {
            const p = v[e], q = v[(e + 1) % 3];
            const lo = Math.min(p, q), hi = Math.max(p, q), key = lo * ids + hi;
            let h = mix(lo ^ mix(hi ^ seed)) & (edgeSize - 1);
            while (keys[h] !== -1 && keys[h] !== key) {
                if (--budget < 0) return null;
                h = (h + 1) & (edgeSize - 1);
            }
            keys[h] = key;
            uses[h]++;
            ways[h] += p < q ? 1 : -1;
            const a = root(p), b = root(q);
            if (a !== b) parent[a] = b;
        }
    }
    let open = 0, nonManifold = 0, flipped = 0;
    for (let h = 0; h < edgeSize; h++) {
        if (keys[h] === -1) continue;
        if (uses[h] === 1) open++;
        else if (uses[h] > 2) nonManifold++;
        else if (ways[h] !== 0) flipped++;
    }
    // Pieces: of the corners faces use.
    const used = new Uint8Array(ids);
    for (let k = 0; k < triangles * 3; k++) {
        const c = corner(k);
        if (c >= 0) used[c] = 1;
    }
    let pieces = 0;
    for (let i = 0; i < ids; i++) if (used[i] && root(i) === i) pieces++;
    return { open, nonManifold, flipped, pieces };
}

// meshCheckText is what's said of a check (see meshCheck), or "" if there
// wasn't one: "watertight", or what's wrong; and how many pieces.
export function meshCheckText(check) {
    if (!check) return "";
    const plural = (n, one, many = `${one}s`) => `${n.toLocaleString("en")} ${n === 1 ? one : many}`;
    const wrong = [check.open && plural(check.open, "open edge"), check.nonManifold && plural(check.nonManifold, "non-manifold edge"),
        check.flipped && plural(check.flipped, "flipped edge")].filter(Boolean);
    const pieces = check.pieces > 1 ? `${check.pieces.toLocaleString("en")} pieces` : "";
    return [wrong.length ? wrong.join(", ") : "watertight", pieces].filter(Boolean).join(" · ");
}

// combineChecks is several meshes' checks, together (null if any wasn't).
export function combineChecks(checks) {
    if (!checks.length || checks.some((c) => !c)) return null;
    return checks.reduce((a, c) => ({ open: a.open + c.open, nonManifold: a.nonManifold + c.nonManifold, flipped: a.flipped + c.flipped, pieces: a.pieces + c.pieces }),
        { open: 0, nonManifold: 0, flipped: 0, pieces: 0 });
}

files.tabtop/model-limits.js:
// How much a Collada or VRML file makes, counted before three.js's loaders
// read it: each copies a shared part every time it's used (Collada's
// <instance_node>, VRML's USE), so a file of a few kilobytes, each level
// using the one below twice, makes millions, and freezes or crashes the
// page. Counted from the text, each use in full: {nodes, shapes}. A scan
// of each, linear (no pattern that goes back over what it read).

// Collada (and a KMZ's): read on the page, so less of it.
export const MAX_COLLADA = { nodes: 100_000, shapes: 10_000 };
// VRML: read in the model worker.
export const MAX_VRML_MADE = { nodes: 500_000, shapes: 50_000 };

const add = (a, b) => ({ nodes: Math.min(a.nodes + b.nodes, 1e15), shapes: Math.min(a.shapes + b.shapes, 1e15) });
const over = (made, max) => made.nodes > max.nodes || made.shapes > max.shapes;
const tooMany = (made) => new Error(`it makes too many parts to show here (${made.shapes > 1e9 ? "billions of" : Math.round(made.shapes).toLocaleString("en")} shapes, ${made.nodes > 1e9 ? "billions of" : Math.round(made.nodes).toLocaleString("en")} nodes, once each shared part is counted where it's used)`);

// colladaMade is what a Collada document's scenes make: its nodes, and
// the geometries (and controllers) they place. A node used by
// <instance_node> is counted each time; one that uses itself, at any
// remove, is refused.
export function colladaMade(text) {
    // Each node's own count, the nodes in it, and those it uses, by id.
    const nodes = [], byId = new Map(), roots = [];
    const stack = [];
    let inScene = 0;
    const tag = /<\s*(\/?)([\w:.-]+)((?:[^\w:.<>-][^<>]*)?)>/g;
    const attr = (rest, name) => {
        const m = new RegExp(`(?<![\\w:.-])${name}\\s*=\\s*("([^"]*)"|'([^']*)')`).exec(rest);
        return m ? m[2] ?? m[3] : null;
    };
    for (let m; (m = tag.exec(text));) {
        const [, closing, raw, rest] = m;
        const name = raw.slice(raw.lastIndexOf(":") + 1);
        const selfClosing = /\/\s*$/.test(rest);
        if (name === "visual_scene") { if (closing) inScene--; else if (!selfClosing) inScene++; continue; }
        if (name === "node") {
            if (closing) { stack.pop(); continue; }
            const node = { own: { nodes: 1, shapes: 0 }, children: [], uses: [] };
            nodes.push(node);
            const id = attr(rest, "id");
            if (id !== null && !byId.has(id)) byId.set(id, node);
            if (stack.length) stack.at(-1).children.push(node);
            else if (inScene > 0) roots.push(node);
            if (!selfClosing) stack.push(node);
            continue;
        }
        if (closing || !stack.length) continue;
        if (name === "instance_node") stack.at(-1).uses.push((attr(rest, "url") ?? "").replace(/^#/, ""));
        else if (name === "instance_geometry" || name === "instance_controller") stack.at(-1).own.shapes++;
    }
    // Each node's whole count, worked out once (depth first, without
    // recursion: a file nested deep doesn't overflow the stack).
    const made = new Map(), working = new Set();
    const total = (start) => {
        const todo = [[start, false]];
        while (todo.length) {
            const [node, expanded] = todo.pop();
            if (made.has(node)) continue;
            const deps = [...node.children, ...node.uses.map((id) => byId.get(id)).filter(Boolean)];
            if (!expanded) {
                if (working.has(node)) throw new Error("it uses a part inside itself");
                working.add(node);
                todo.push([node, true]);
                for (const d of deps) if (!made.has(d)) {
                    if (working.has(d)) throw new Error("it uses a part inside itself");
                    todo.push([d, false]);
                }
                continue;
            }
            working.delete(node);
            made.set(node, deps.reduce((sum, d) => add(sum, made.get(d)), node.own));
        }
        return made.get(start);
    };
    return roots.reduce((sum, r) => add(sum, total(r)), { nodes: 0, shapes: 0 });
}

// checkCollada throws if a Collada document makes more than max.
export function checkCollada(text, max = MAX_COLLADA) {
    const made = colladaMade(text);
    if (over(made, max)) throw tooMany(made);
    return made;
}

// vrmlMade is what a VRML (97) file makes: each node (each "{ … }" that
// a type name opens), its Shapes, and what each USE uses, counted again.
// Comments and strings are passed over.
export function vrmlMade(text, max = MAX_VRML_MADE) {
    const defs = new Map();
    const stack = [{ made: { nodes: 0, shapes: 0 }, def: null }];
    let def = null, type = null;
    // (A string not closed runs to the end, once: none is gone over twice.)
    const token = /#[^\n]*|"(?:[^"\\]|\\.)*"?|[{}]|[^\s{}[\],"#]+/g;
    let previous = "";
    for (let m; (m = token.exec(text));) {
        const t = m[0];
        if (t[0] === "#" || t[0] === "\"") { previous = ""; continue; }
        if (t === "{") {
            stack.push({ made: { nodes: 1, shapes: type === "Shape" ? 1 : 0 }, def });
            def = type = null;
        } else if (t === "}") {
            if (stack.length < 2) continue;
            const node = stack.pop();
            if (node.def !== null) defs.set(node.def, node.made);
            stack.at(-1).made = add(stack.at(-1).made, node.made);
        } else if (previous === "DEF") {
            def = t;
        } else if (previous === "USE") {
            stack.at(-1).made = add(stack.at(-1).made, defs.get(t) ?? { nodes: 1, shapes: 0 });
        } else {
            type = t;
        }
        if (over(stack.at(-1).made, max)) throw tooMany(stack.at(-1).made);
        previous = t;
    }
    let made = { nodes: 0, shapes: 0 };
    for (const f of stack) made = add(made, f.made);
    if (over(made, max)) throw tooMany(made);
    return made;
}

files.tabtop/model-looks.js:
// How a model's surfaces are shown, in the 3D preview (model-view.js),
// for looking it over before printing it:
//   - its look: its own materials; or its overhangs (faces facing down
//     more than an angle from level, but those on the plate), which need
//     support printed under them; or its faces inside out (their backs
//     showing: holes, or faces the wrong way round); or X-ray (see through);
//   - its sharp edges (those between faces more than 30° apart) drawn on it;
//   - smooth (each face's normals as its neighbours', but across sharp
//     edges) or faceted (each face flat);
//   - a section: the model cut away above a height, what's cut filled.
// Every material it has is given the same small addition to its shader
// (see patch): its look, and the cut, as uniforms all share.
import { el, glyphChoice } from "./preview-dom.js";

export const LOOKS = { materials: "Materials", overhang: "Overhangs", inside: "Faces inside out", xray: "X-ray" };
const CREASE = 30;            // degrees: an edge sharper than this is drawn, and kept sharp, smooth
const MAX_EDGED = 3e6;        // triangles: more aren't given edges, nor smoothed (made at once, on the page)

// lookTools is the tools for meshes' looks (and what they need): {tools
// (the bar's controls), placed(box) (the model's placed: its plate's
// height, box.min.y), stop()}. button and toggle make the bar's buttons, as
// model-view.js does; redraw draws it again. faceted says its meshes are
// flat facets only (an STL's, a 3MF's: no normals of their own to smooth
// with); otherwise, they're shown smooth as they are to begin with.
export function lookTools(THREE, meshes, { renderer, redraw, button, toggle, faceted = false }) {
    const triangles = meshes.reduce((n, m) => n + (m.geometry.index ? m.geometry.index.count : m.geometry.attributes.position.count) / 3, 0);
    const u = {
        uLook: { value: 0 }, uCos: { value: Math.cos(THREE.MathUtils.degToRad(45)) }, uBed: { value: 0 }, uEps: { value: 1e-3 }, uCap: { value: false },
        uOverhang: { value: new THREE.Color(0xe2462e) }, uBase: { value: new THREE.Color(0xa9b7c9) }, uInside: { value: new THREE.Color(0xd9423b) }, uCut: { value: new THREE.Color(0xe08a3c) },
    };
    const patched = new Set();
    const patch = (material) => {
        if (patched.has(material)) return;
        patched.add(material);
        material.onBeforeCompile = (shader) => {
            Object.assign(shader.uniforms, u);
            // (Where it is in the scene: an instance's, or a batch's, placed as it is.)
            shader.vertexShader = "varying vec3 vLookWorld;\n" + shader.vertexShader.replace("#include <project_vertex>", `#include <project_vertex>
	vec4 lookAt = vec4(transformed, 1.0);
	#ifdef USE_BATCHING
		lookAt = batchingMatrix * lookAt;
	#endif
	#ifdef USE_INSTANCING
		lookAt = instanceMatrix * lookAt;
	#endif
	vLookWorld = (modelMatrix * lookAt).xyz;`);
            shader.fragmentShader = "varying vec3 vLookWorld;\nuniform int uLook;\nuniform float uCos, uBed, uEps;\nuniform bool uCap;\nuniform vec3 uOverhang, uBase, uInside, uCut;\n" +
                shader.fragmentShader.replace("#include <color_fragment>", `#include <color_fragment>
	if (uLook == 1) {
		// The face's own normal, outward (its derivatives' cross is towards the eye: a back's, away).
		vec3 faceNormal = normalize(cross(dFdx(vLookWorld), dFdy(vLookWorld)));
		if (!gl_FrontFacing) faceNormal = -faceNormal;
		diffuseColor.rgb = (-faceNormal.y > uCos && vLookWorld.y > uBed + uEps) ? uOverhang : uBase;
	} else if (uLook == 2) {
		diffuseColor.rgb = gl_FrontFacing ? uBase : uInside;
	}
	if (uCap && !gl_FrontFacing) diffuseColor.rgb = uCut;`);
        };
        material.customProgramCacheKey = () => "tabtop-looks";
        material.needsUpdate = true;
    };
    // Each mesh's own material(s), and theirs sides and shading, to go back to.
    const originals = new Map(meshes.map((m) => [m, { material: m.material, sides: [m.material].flat().map((mat) => mat.side), flats: [m.material].flat().map((mat) => mat.flatShading) }]));
    for (const m of meshes) [m.material].flat().forEach(patch);
    const xray = new THREE.MeshStandardMaterial({ color: 0x8fa8c8, transparent: true, opacity: 0.25, depthWrite: false, side: THREE.DoubleSide, roughness: 0.6 });
    patch(xray);
    const plane = new THREE.Plane(new THREE.Vector3(0, -1, 0), 0);
    const edgeMaterial = new THREE.LineBasicMaterial({ color: 0x1d2430, transparent: true, opacity: 0.8 });
    let look = "materials", wireframe = false, sectioned = false, edges = null, smooth = !faceted, smoothed = null, smoothing = null;

    // apply shows the meshes as look, wireframe, sectioned and smooth say.
    const apply = () => {
        u.uLook.value = look === "overhang" ? 1 : look === "inside" ? 2 : 0;
        u.uCap.value = sectioned;
        for (const m of meshes) {
            const was = originals.get(m);
            m.material = look === "xray" ? xray : was.material;
            [m.material].flat().forEach((mat, i) => {
                // (Their backs shown, where it's their backs that are looked for, or cut into.)
                const side = look === "inside" || look === "overhang" || sectioned || mat === xray ? THREE.DoubleSide : was.sides[i] ?? mat.side;
                // Smooth: as it is (its own normals; facets made smooth, for
                // a faceted one); faceted: each face flat.
                const flat = smooth ? (mat === xray || smoothed?.has(m) ? false : was.flats[i] ?? false) : true;
                const clip = sectioned ? [plane] : null;
                if (mat.side !== side || mat.flatShading !== flat || (mat.clippingPlanes?.length ?? 0) !== (clip?.length ?? 0)) mat.needsUpdate = true;
                mat.side = side;
                mat.flatShading = flat;
                mat.clippingPlanes = clip;
                mat.wireframe = wireframe;
            });
            if (smoothed) m.geometry = smooth ? smoothed.get(m) ?? smoothed.original.get(m) : smoothed.original.get(m);
        }
        edgeMaterial.clippingPlanes = sectioned ? [plane] : null;
        edgeMaterial.needsUpdate = true;
        renderer.localClippingEnabled = sectioned;
        redraw();
    };

    // The look, and the overhang's angle (shown for overhangs).
    const lookIcons = { materials: "materials", overhang: "overhang", inside: "inside", xray: "xray" };
    const pick = glyphChoice({ className: "model-look", title: "How its surfaces are shown", value: look,
        choices: Object.entries(LOOKS).map(([value, label]) => ({ value, label, icon: lookIcons[value] })),
        change(value) { look = value; angleBox.hidden = look !== "overhang"; apply(); },
    });
    const angle = el("input", { type: "number", className: "model-angle", min: "1", max: "89", step: "1", value: "45", ariaLabel: "Overhang angle, degrees from straight down",
        title: "Faces facing down more steeply than this many degrees from level are overhangs" });
    const angleBox = el("label", { className: "model-angle-box", hidden: true, title: angle.title }, angle, "°");
    angle.addEventListener("input", () => {
        const a = Math.max(1, Math.min(89, Number(angle.value) || 45));
        // Overhanging: facing down more than a degrees from level, so its normal's within (90 - a) of straight down.
        u.uCos.value = Math.cos(THREE.MathUtils.degToRad(90 - a));
        redraw();
    });
    u.uCos.value = Math.cos(THREE.MathUtils.degToRad(45));

    const wire = toggle("", "Wireframe: show its triangles' edges only", false, (on) => { wireframe = on; apply(); }, "wireframe");
    wire.classList.add("model-wireframe");

    const sharp = toggle("", `Edges: draw its sharp edges (where faces meet at more than ${CREASE}°)`, false, (on) => {
        if (on && !edges) {
            edges = [];
            for (const m of meshes) {
                // (Not an instanced mesh's: its edges would be drawn once, not for each.)
                if (m.isSkinnedMesh || m.isInstancedMesh || m.isBatchedMesh) continue;
                const line = new THREE.LineSegments(new THREE.EdgesGeometry(m.geometry, CREASE), edgeMaterial);
                line.raycast = () => {};
                m.add(line);
                edges.push(line);
            }
        }
        for (const line of edges ?? []) line.visible = on;
        apply();
    }, "edges");
    sharp.classList.add("model-edges");
    if (triangles > MAX_EDGED) { sharp.disabled = true; sharp.title = `Edges: it has too many triangles (${triangles.toLocaleString("en")}) to find them here`; }

    const said = (b) => {
        b.title = smooth ? "Smooth: its faces shaded smooth, but across sharp edges (click for faceted)" : "Faceted: each face shaded flat (click for smooth)";
        b.setAttribute("aria-label", b.title);
        b.setAttribute("aria-pressed", String(smooth));
    };
    const shading = toggle("", "", smooth, async function (on) {
        smooth = on;
        said(this);
        if (on && faceted && !smoothed) {
            // Facets only (an STL's): normals made smooth, but across sharp
            // edges; made once (clicked again meanwhile: the same making).
            smoothing ??= import("./three/BufferGeometryUtils.js").then(({ toCreasedNormals }) => {
                const made = new Map();
                made.original = new Map(meshes.map((m) => [m, m.geometry]));
                // (Those with faces each their own corners, or no normals at all.)
                for (const m of meshes) {
                    if (m.isSkinnedMesh || m.isInstancedMesh || m.isBatchedMesh) continue;
                    if (!m.geometry.index || !m.geometry.attributes.normal) made.set(m, toCreasedNormals(m.geometry, THREE.MathUtils.degToRad(CREASE)));
                }
                smoothed = made;
            });
            await smoothing;
            said(this); // (as it is now: clicked meanwhile, perhaps)
        }
        apply();
    }, "smooth");
    shading.classList.add("model-smooth");
    said(shading);
    if (triangles > MAX_EDGED && faceted) shading.disabled = true;

    // The section: cut away above the slider's height (of the model's).
    let bottom = 0, top = 1;
    const height = el("input", { type: "range", className: "model-section-height", min: "0", max: "1000", value: "500", step: "1", ariaLabel: "Cut at height", hidden: true });
    const cutAt = () => { plane.constant = bottom + (top - bottom) * Number(height.value) / 1000; redraw(); };
    height.addEventListener("input", cutAt);
    const section = toggle("", "Section: cut it away above a height (the slider), to see inside", false, (on) => {
        sectioned = on;
        height.hidden = !on;
        cutAt();
        apply();
    }, "section");
    section.classList.add("model-section");
    apply();
    return {
        tools: [pick, angleBox, wire, sharp, shading, section, height],
        // The model placed: its plate's height, and how high it is (what's
        // overhanging is above the plate; the section's within it).
        placed(box) {
            bottom = box.min.y;
            top = box.max.y;
            u.uBed.value = box.min.y;
            u.uEps.value = Math.max(1e-6, (box.max.y - box.min.y) * 1e-3);
            cutAt();
        },
        stop() {
            xray.dispose();
            edgeMaterial.dispose();
            for (const line of edges ?? []) line.geometry.dispose();
            // Both forms of each, whichever is shown (the view lets go of that one too).
            for (const g of smoothed?.values() ?? []) g.dispose();
            for (const g of smoothed?.original.values() ?? []) g.dispose();
        },
    };
}

files.tabtop/model-read.js:
// readResource reads a file a 3D model refers to (see model-resources.js),
// at path in the files' root, as a Blob of its type, or throws if it isn't
// there or is bigger than MAX_RESOURCE (an error with tooBig). (model-view.js's default; a page
// of its own can read them another way.)
import { call, collect } from "./requests.js";
import { typeOf } from "./preview-model.js";
import { MAX_RESOURCE } from "./model-resources.js";

export async function readResource(path, signal) {
    const t = await call({ type: "file", path }, { signal });
    const abort = () => t.close();
    signal?.addEventListener("abort", abort, { once: true });
    try {
        if (t.reply.size > MAX_RESOURCE) throw Object.assign(new Error("it's too big"), { tooBig: true });
        return await collect(t, t.reply.size, () => {}, typeOf(path.split("/").pop())?.type ?? "application/octet-stream");
    } finally {
        signal?.removeEventListener("abort", abort);
        t.close();
    }
}

files.tabtop/model-resources.js:
// The files a 3D model refers to (glTF's buffers and pictures, an OBJ's
// materials, .mtl, and their textures, an FBX's textures), read from
// beside it, for model-view.js: found where the model says, relative to
// its folder; else, by name alone, in its folder (as a model made
// elsewhere names them where they were there: C:\Users\…\wood.png). Never
// from the web, nor outside the files' root (the server sees to that).
import { resolvePath } from "./preview-model.js";

// At most this many files are read for a model, each at most
// MAX_RESOURCE bytes, all of them at most MAX_RESOURCES_TOTAL.
export const MAX_RESOURCE_FILES = 64;
export const MAX_RESOURCE = 64 << 20;
export const MAX_RESOURCES_TOTAL = 256 << 20;
// At most this many of what a model names are looked for (found or not:
// one naming thousands that aren't there doesn't have them all asked for).
export const MAX_RESOURCE_LOOKUPS = 4 * MAX_RESOURCE_FILES;

// What a model's reference to a file that isn't there is given: a URL a
// loader can load, so it doesn't go elsewhere; a picture of one white,
// opaque pixel, so a texture that isn't there leaves its colour as it is
// (not black, as a see-through one would make it).
export const BLANK = "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAIAAACQd1PeAAAADElEQVR4nGP4//8/AAX+Av4N70a4AAAAAElFTkSuQmCC";

const join = (dir, name) => (dir ? `${dir}/${name}` : name);

// resourceCandidates is where the file a model in dir refers to as ref
// may be, in the order they're tried: the paths, within the files' root.
// uri says ref is a URI (glTF's are: percent-encoded); otherwise it's a
// name as written (an MTL's, an FBX's). A web address, or a data: or
// blob: URL, isn't one of these: none. A name alone is also looked for in
// the folders near names, beside the model (an FBX's own .fbm folder,
// textures/: FBX's loader leaves only the name of what's in a folder).
export function resourceCandidates(dir, ref, { uri = false, near = [] } = {}) {
    let r = String(ref ?? "").trim();
    if (!r) return [];
    // A scheme, but not a Windows drive (C:\ or C:/).
    if (/^[a-z][a-z0-9+.-]*:/i.test(r) && !/^[a-z]:[\\/]/i.test(r)) return [];
    if (!uri) r = r.split(/[\\/]/).map(encodeURIComponent).join("/");
    else r = r.replace(/\\/g, "/");
    const segments = r.split("/").filter(Boolean);
    const name = segments.at(-1) ?? "";
    const out = [];
    const absolute = r.startsWith("/") || /^[a-z]%3A$/i.test(segments[0] ?? "") || /^[a-z]:$/i.test(segments[0] ?? "");
    if (!absolute) {
        const p = resolvePath(dir, segments.join("/"));
        if (p) out.push(p);
    }
    const alone = name && resolvePath(dir, name);
    if (alone && !out.includes(alone)) out.push(alone);
    if (segments.length === 1 && name) {
        for (const folder of near) {
            const p = resolvePath(dir, `${encodeURIComponent(folder)}/${name}`);
            if (p && !out.includes(p)) out.push(p);
        }
    }
    return out;
}

// fetchResources reads what a model in dir refers to, refs, with read
// (path, signal) => a Blob, or throwing if it isn't there. It resolves to
// {urls: a Map of each ref found to a blob: URL of it, blobs and paths (of
// each ref found: what it is, and where), missing: the refs not (of them,
// tooBig: those there, but too big to read), revoke() to let the URLs go}.
// With uri, refs are URIs; near, folders names alone are looked for in
// too (see above).
export async function fetchResources(dir, refs, read, { uri = false, near = [], signal } = {}) {
    const urls = new Map(), blobs = new Map(), paths = new Map(), missing = [], tooBig = [], made = [];
    let total = 0, files = 0, lookups = 0;
    for (const ref of [...new Set(refs)]) {
        signal?.throwIfAborted();
        const candidates = resourceCandidates(dir, ref, { uri, near });
        let blob = null, found = "";
        if (files < MAX_RESOURCE_FILES && candidates.length && lookups++ < MAX_RESOURCE_LOOKUPS) {
            for (const path of candidates) {
                try {
                    blob = await read(path, signal);
                } catch (err) {
                    if (signal?.aborted) throw err;
                    // (There, but too big: said so, not looked for elsewhere.)
                    if (err?.tooBig) {
                        tooBig.push(ref);
                        break;
                    }
                    continue;
                }
                if (blob.size > MAX_RESOURCE || total + blob.size > MAX_RESOURCES_TOTAL) {
                    blob = null;
                    tooBig.push(ref);
                }
                found = path;
                break;
            }
        }
        if (!blob) {
            if (candidates.length) missing.push(ref);
            continue;
        }
        files++;
        total += blob.size;
        const url = URL.createObjectURL(blob);
        made.push(url);
        urls.set(ref, url);
        blobs.set(ref, blob);
        paths.set(ref, found);
    }
    return { urls, blobs, paths, missing, tooBig, revoke: () => made.forEach((u) => URL.revokeObjectURL(u)) };
}

// gltfReferences is what a glTF's JSON (parsed) refers to by URI, not
// data: URLs: its buffers', then its pictures'.
export function gltfReferences(json) {
    return [...(json.buffers ?? []), ...(json.images ?? [])].map((x) => x?.uri).filter((u) => typeof u === "string" && !/^data:/i.test(u));
}

// glbJSON is a .glb's JSON, parsed (its first chunk), or throws.
export function glbJSON(buffer) {
    const v = new DataView(buffer);
    if (buffer.byteLength < 20 || v.getUint32(0, true) !== 0x46546c67) throw new Error("it isn't a binary glTF");
    const length = v.getUint32(12, true);
    if (v.getUint32(16, true) !== 0x4e4f534a || 20 + length > buffer.byteLength) throw new Error("its JSON is missing");
    return JSON.parse(new TextDecoder().decode(new Uint8Array(buffer, 20, length)));
}

// COMPRESSED are the glTF extensions model-decode.js decodes (in a worker:
// Draco's meshes, meshopt's buffers, KTX2 textures).
export const COMPRESSED = new Set(["KHR_draco_mesh_compression", "EXT_meshopt_compression", "KHR_meshopt_compression", "KHR_texture_basisu"]);

// fbxText is an FBX's text, if it's a text (ASCII) one, not binary, made
// what three.js's FBX loader reads; else null. That loader turns the first
// space in each part of a property ("P:" line) into "_" (so "Lcl Rotation"
// is "Lcl_Rotation"), so values written with spaces after their commas
// (-90, -0, 0: as Assimp and others write them; Autodesk's own don't)
// aren't numbers to it, and the model's transforms are lost: those spaces
// taken out (of what's after a line's last quoted part, only). And it
// makes numbers only of properties of the types it knows: a texture's
// Scaling and Translation, of type "Vector" (as Autodesk's, too, write
// them), stay text, so the texture's repeat is nonsense: "Vector",
// "Vector2D" and "Vector4D" called "Vector3D", which it knows.
export function fbxText(bytes) {
    const head = new TextDecoder("latin1").decode(bytes.subarray(0, 20));
    if (head.startsWith("Kaydara FBX Binary")) return null;
    const text = new TextDecoder().decode(bytes);
    return text
        // (Spaces and tabs only, not \s: that runs over line ends, and a file
        // of many blank lines took time growing with their square.)
        .replace(/^([ \t]*P:[^\n]*")([^"\n]*)$/gm, (_, quoted, values) => quoted + values.replace(/,[ \t]+/g, ","))
        .replace(/^([ \t]*P:[ \t]*"[^"\n]*",[ \t]*")(?:Vector|Vector2D|Vector4D)(")/gm, "$1Vector3D$2");
}

// fbxTextVersion is a text FBX's version (7500 for 7.5), or 0 if it doesn't say.
export function fbxTextVersion(text) {
    const m = /^\s*FBXVersion:\s*(\d+)/m.exec(text.slice(0, 4096)) ?? /^; FBX (\d+)\.(\d+)/m.exec(text.slice(0, 200));
    if (!m) return 0;
    return m[2] !== undefined ? Number(m[1]) * 1000 + Number(m[2]) * 100 : Number(m[1]);
}

files.tabtop/model-thumbnails.js:
// The pictures 3D printing files have of themselves, for the files page's
// grid (see thumbnails.js): a slicer's 3MF's (Metadata/thumbnail.png, or
// a plate's), G-code's (base64 in comments at its start: "; thumbnail
// begin 300x300 12345" … "; thumbnail end", as PrusaSlicer, Cura, Orca and
// Bambu Studio write them), and binary G-code's (thumbnail blocks, before
// its G-code). Only what's needed is read (readRange): a 3MF's directory,
// at its end, and the one picture; G-code's start. Of several, the
// largest PNG or JPEG is taken (QOI, which browsers don't show, isn't).

export const MODEL_THUMBNAIL = /\.(?:3mf|gcode|gco|bgcode)$/i;
const HEAD = 2 << 20;            // the start of a G-code file, where its pictures are looked for
const MAX_IMAGE = 8 << 20;       // a picture bigger than this isn't taken
const MAX_DIRECTORY = 4 << 20;   // a 3MF's directory, at most
const MAX_BLOCKS = 256;          // binary G-code's blocks looked through, at most

// picture is {bytes, type} if bytes are a PNG's or a JPEG's (by their
// first bytes, not by what the file says), else null.
function picture(bytes) {
    if (bytes.length > 8 && bytes[0] === 0x89 && bytes[1] === 0x50 && bytes[2] === 0x4e && bytes[3] === 0x47) return { bytes, type: "image/png" };
    if (bytes.length > 3 && bytes[0] === 0xff && bytes[1] === 0xd8 && bytes[2] === 0xff) return { bytes, type: "image/jpeg" };
    return null;
}
const largest = (found) => found.filter((f) => f.picture).sort((a, b) => b.pixels - a.pixels)[0]?.picture ?? null;

// modelThumbnail is the picture the file named name, size bytes long,
// has of itself ({bytes, type}), or null. readRange(offset, length)
// resolves to those bytes of it (fewer at its end).
export async function modelThumbnail(name, size, readRange) {
    const ext = name.slice(name.lastIndexOf(".") + 1).toLowerCase();
    if (ext === "3mf") return zipThumbnail(size, readRange);
    if (ext === "bgcode") return bgcodeThumbnail(await readRange(0, Math.min(size, HEAD)));
    if (ext === "gcode" || ext === "gco") return gcodeThumbnail(await readRange(0, Math.min(size, HEAD)));
    return null;
}

// gcodeThumbnail is the largest picture in G-code text's comments.
export function gcodeThumbnail(bytes) {
    // (Latin-1: one character a byte; base64 is ASCII.)
    const text = new TextDecoder("latin1").decode(bytes);
    const found = [];
    const begin = /^;[ \t]*thumbnail(?:_(PNG|JPG|QOI))?[ \t]+begin[ \t]+(\d+)[ \t]*x[ \t]*(\d+)[ \t]+(\d+)/gm;
    for (let m; (m = begin.exec(text));) {
        const [, format = "PNG", w, h, length] = m;
        const end = text.indexOf(`thumbnail${m[1] ? `_${m[1]}` : ""} end`, begin.lastIndex);
        if (end < 0) break; // cut off by the end of what was read
        begin.lastIndex = end;
        if (format === "QOI" || Number(length) > MAX_IMAGE * 4 / 3) continue;
        // Its lines, each "; " and base64.
        const base64 = text.slice(text.indexOf("\n", m.index) + 1, text.lastIndexOf("\n", end)).replace(/^;[ \t]?/gm, "").replace(/\s+/g, "");
        let decoded;
        try {
            decoded = Uint8Array.from(atob(base64), (c) => c.charCodeAt(0));
        } catch {
            continue;
        }
        found.push({ pixels: Number(w) * Number(h), picture: picture(decoded) });
    }
    return largest(found);
}

// bgcodeThumbnail is the largest picture in binary G-code's thumbnail
// blocks (see bgcode.js: they come before its G-code).
export function bgcodeThumbnail(bytes) {
    const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
    if (bytes.length < 10 || view.getUint32(0, true) !== 0x45444347) return null;
    const checksum = view.getUint16(8, true) ? 4 : 0;
    const found = [];
    let at = 10;
    for (let n = 0; n < MAX_BLOCKS && at + 12 <= bytes.length; n++) {
        const type = view.getUint16(at, true), compression = view.getUint16(at + 2, true), size = view.getUint32(at + 4, true);
        const packed = compression ? view.getUint32(at + 8, true) : size;
        const head = compression ? 12 : 8, params = type === 5 ? 6 : 2;
        if (type === 1) break; // its G-code: no more pictures
        if (type === 5 && compression === 0 && at + head + params + size <= bytes.length && size <= MAX_IMAGE) {
            const format = view.getUint16(at + head, true), w = view.getUint16(at + head + 2, true), h = view.getUint16(at + head + 4, true);
            if (format === 0 || format === 1) found.push({ pixels: w * h, picture: picture(bytes.slice(at + head + params, at + head + params + size)) });
        }
        at += head + params + packed + checksum;
    }
    return largest(found);
}

// The picture a 3MF has, by its name: the package's own (Metadata/
// thumbnail.png), else a plate's, else any other in Metadata/ but a
// "pick" one (Bambu Studio's: its parts, coloured to tell them apart).
function rank(name) {
    const n = name.toLowerCase();
    if (n === "metadata/thumbnail.png" || n === "metadata/thumbnail.jpg") return 0;
    if (/^metadata\/plate_1\.(png|jpg)$/.test(n)) return 1;
    if (/^metadata\/plate_\d+\.(png|jpg)$/.test(n)) return 2;
    if (/^metadata\/(?!pick_)[^/]+\.(png|jpe?g)$/.test(n)) return 3;
    return -1;
}

// zipThumbnail is the picture in a 3MF (a ZIP): its directory read from
// its end, then the one entry.
export async function zipThumbnail(size, readRange) {
    const tailLength = Math.min(size, 22 + 0xffff);
    const tail = await readRange(size - tailLength, tailLength);
    const tv = new DataView(tail.buffer, tail.byteOffset, tail.byteLength);
    let end = -1;
    for (let i = tail.length - 22; i >= 0; i--) if (tv.getUint32(i, true) === 0x06054b50) { end = i; break; }
    if (end < 0) return null;
    const dirSize = tv.getUint32(end + 12, true), dirOffset = tv.getUint32(end + 16, true);
    if (dirSize > MAX_DIRECTORY || dirOffset + dirSize > size) return null;
    const tailStart = size - tailLength;
    const dir = dirOffset >= tailStart ? tail.subarray(dirOffset - tailStart, dirOffset - tailStart + dirSize) : await readRange(dirOffset, dirSize);
    const dv = new DataView(dir.buffer, dir.byteOffset, dir.byteLength);
    const decoder = new TextDecoder();
    let best = null;
    for (let at = 0; at + 46 <= dir.length && dv.getUint32(at, true) === 0x02014b50;) {
        const nameLength = dv.getUint16(at + 28, true);
        const entry = {
            method: dv.getUint16(at + 10, true), packed: dv.getUint32(at + 20, true), size: dv.getUint32(at + 24, true),
            offset: dv.getUint32(at + 42, true), name: decoder.decode(dir.subarray(at + 46, at + 46 + nameLength)),
        };
        const r = rank(entry.name);
        if (r >= 0 && (!best || r < best.rank)) best = { ...entry, rank: r };
        at += 46 + nameLength + dv.getUint16(at + 30, true) + dv.getUint16(at + 32, true);
    }
    if (!best || best.size > MAX_IMAGE || best.packed > MAX_IMAGE || (best.method !== 0 && best.method !== 8)) return null;
    const local = await readRange(best.offset, 30);
    const lv = new DataView(local.buffer, local.byteOffset, local.byteLength);
    if (local.length < 30 || lv.getUint32(0, true) !== 0x04034b50) return null;
    const data = await readRange(best.offset + 30 + lv.getUint16(26, true) + lv.getUint16(28, true), best.packed);
    if (data.length !== best.packed) return null;
    return picture(best.method === 0 ? data : await inflate(data, best.size));
}

// inflate is Deflate'd data unpacked (by the browser's own), into no more
// than size bytes: what's past that isn't unpacked.
async function inflate(data, size) {
    const reader = new Blob([data]).stream().pipeThrough(new DecompressionStream("deflate-raw")).getReader();
    const out = new Uint8Array(size);
    let at = 0;
    try {
        for (;;) {
            const { done, value } = await reader.read();
            if (done) break;
            if (at + value.length > size) throw new Error("it unpacks to more than it says");
            out.set(value, at);
            at += value.length;
        }
    } finally {
        reader.cancel().catch(() => {});
    }
    return out.subarray(0, at);
}

