        if (!/^(_rels\/|3D\/|Metadata\/plate_\d+\.gcode$)/i.test(f.name)) return false;
        unpacked += f.originalSize;
        if (unpacked > MAX_UNZIPPED) throw new Error(`it's too big to unpack here (it unpacks to more than ${MAX_UNZIPPED >> 20} MB)`);
        return true;
    };
