// turn waits till fewer than AT_ONCE are being made.
function turn(signal) {
    if (running < AT_ONCE) {
        running++;
        return Promise.resolve();
    }
    return new Promise((resolve, reject) => {
        const go = () => {
            signal.removeEventListener("abort", stop);
            running++;
            resolve();
